149			}
150		}
151	
152		rows, err := d.db.QueryContext(ctx, query, args...)
153		if err != nil {
154			return nil, err
155		}
156		defer rows.Close()
157	
158		list := make([]*store.Memo, 0)
159		for rows.Next() {
160			var memo store.Memo
161			var payloadBytes []byte
162			dests := []any{
163				&memo.ID,
164				&memo.UID,
165				&memo.CreatorID,
166				&memo.CreatedTs,
167				&memo.UpdatedTs,
168				&memo.RowStatus,
