202	func (d *DB) UpdateMemo(ctx context.Context, update *store.UpdateMemo) error {
203		set, args := []string{}, []any{}
204		if v := update.UID; v != nil {
205			set, args = append(set, "uid = "+placeholder(len(args)+1)), append(args, *v)
206		}
207		if v := update.CreatedTs; v != nil {
208			set, args = append(set, "created_ts = "+placeholder(len(args)+1)), append(args, *v)
209		}
210		if v := update.UpdatedTs; v != nil {
211			set, args = append(set, "updated_ts = "+placeholder(len(args)+1)), append(args, *v)
212		}
213		if v := update.RowStatus; v != nil {
214			set, args = append(set, "row_status = "+placeholder(len(args)+1)), append(args, *v)
215		}
216		if v := update.Content; v != nil {
217			set, args = append(set, "content = "+placeholder(len(args)+1)), append(args, *v)
218		}
219		if v := update.Visibility; v != nil {
220			set, args = append(set, "visibility = "+placeholder(len(args)+1)), append(args, *v)
221		}
222		if v := update.Pinned; v != nil {
223			set, args = append(set, "pinned = "+placeholder(len(args)+1)), append(args, *v)
224		}
225		if v := update.Payload; v != nil {
226			payloadBytes, err := protojson.Marshal(v)
227			if err != nil {
228				return err
229			}
230			set, args = append(set, "payload = "+placeholder(len(args)+1)), append(args, string(payloadBytes))
231		}
232		if len(set) == 0 {
233			return nil
234		}
235	
236		stmt := `UPDATE memo SET ` + strings.Join(set, ", ") + ` WHERE id = ` + placeholder(len(args)+1)
237		args = append(args, update.ID)
238		if _, err := d.db.ExecContext(ctx, stmt, args...); err != nil {
239			return err
240		}
241		return nil
242	}
